/**
 * Turn the model's JSON into two validated, deduplicated plans:
 * calendar events and a month-bucketed cost timeline.
 *
 * Everything here is defensive. The schema constrains shape, not sense —
 * a date can still be structurally valid and semantically wrong, and we are
 * about to write to somebody's real calendar.
 */

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const TIME_RE = /^([01]\d|2[0-3]):[0-5]\d$/;
const DEFAULT_TIME = '23:59';   // when a syllabus says a day but not an hour
const DEFAULT_DURATION_MIN = 60;
const MIN_CONFIDENCE = 0.35;

const response = $input.first().json;

// The API returns HTTP 200 for a policy refusal — check before reading content.
if (response.stop_reason === 'refusal') {
  throw new Error(
    'Claude declined to process this document' +
    (response.stop_details?.explanation ? `: ${response.stop_details.explanation}` : '.')
  );
}
if (response.stop_reason === 'max_tokens') {
  throw new Error('Extraction was cut off by the token limit. Try a shorter syllabus.');
}

const textBlock = (response.content || []).find((b) => b.type === 'text');
if (!textBlock) {
  throw new Error('No text block in the Claude response — nothing to parse.');
}

let parsed;
try {
  parsed = JSON.parse(textBlock.text);
} catch (err) {
  throw new Error(`Model returned malformed JSON: ${err.message}`);
}

const meta = $('Sanitize + Guard').first().json;
const timezone = meta.timezone;
const warnings = Array.isArray(parsed.warnings) ? [...parsed.warnings] : [];

if (meta.truncated) {
  warnings.push(
    `The syllabus was truncated at ${meta.charCount} characters — later pages may be missing.`
  );
}

/** Reject dates that are structurally fine but nonsensical for a term. */
function plausibleDate(iso) {
  if (!DATE_RE.test(iso)) return false;
  const d = new Date(`${iso}T12:00:00Z`);
  if (Number.isNaN(d.getTime())) return false;
  // Round-trip guard catches 2026-02-31, which Date silently rolls over.
  if (d.toISOString().slice(0, 10) !== iso) return false;
  const year = d.getUTCFullYear();
  const nowYear = new Date().getUTCFullYear();
  return year >= nowYear - 1 && year <= nowYear + 2;
}

function addMinutes(iso, time, minutes) {
  const [h, m] = time.split(':').map(Number);
  const base = new Date(Date.UTC(
    ...iso.split('-').map(Number).map((v, i) => (i === 1 ? v - 1 : v))
  ));
  base.setUTCHours(h, m + minutes, 0, 0);
  return `${base.toISOString().slice(0, 11)}${String(base.getUTCHours()).padStart(2, '0')}:${String(base.getUTCMinutes()).padStart(2, '0')}:00`;
}

// ---------------------------------------------------------------- deadlines
const seen = new Set();
const events = [];

for (const d of Array.isArray(parsed.deadlines) ? parsed.deadlines : []) {
  if (!d || typeof d.title !== 'string' || !d.title.trim()) continue;

  if (!plausibleDate(d.date)) {
    warnings.push(`Dropped "${d.title}" — unusable date ${JSON.stringify(d.date)}.`);
    continue;
  }
  if (typeof d.confidence === 'number' && d.confidence < MIN_CONFIDENCE) {
    warnings.push(`Dropped "${d.title}" — confidence ${d.confidence.toFixed(2)} too low to trust.`);
    continue;
  }

  // Same title on the same day twice is a duplicate, not two obligations.
  const key = `${d.date}|${d.title.trim().toLowerCase()}`;
  if (seen.has(key)) continue;
  seen.add(key);

  const time = TIME_RE.test(d.time || '') ? d.time : DEFAULT_TIME;
  const startLocal = `${d.date}T${time}:00`;
  const weight = typeof d.weight_percent === 'number' ? d.weight_percent : null;

  const descriptionLines = [
    d.notes?.trim(),
    weight !== null ? `Worth ${weight}% of the final grade.` : null,
    d.source_quote?.trim() ? `\nFrom the syllabus:\n"${d.source_quote.trim()}"` : null,
    typeof d.confidence === 'number' && d.confidence < 0.6
      ? `\n[Low confidence (${d.confidence.toFixed(2)}) — this date was inferred. Verify it.]`
      : null,
    `\nAuto-imported from ${meta.sourceName}.`,
  ].filter(Boolean);

  events.push({
    summary: `${parsed.course?.code ? parsed.course.code + ': ' : ''}${d.title.trim()}`,
    start: startLocal,
    end: addMinutes(d.date, time, DEFAULT_DURATION_MIN),
    timezone,
    description: descriptionLines.join('\n'),
    kind: d.kind || 'other',
    date: d.date,
    weightPercent: weight,
    confidence: d.confidence ?? null,
  });
}

events.sort((a, b) => a.start.localeCompare(b.start));

// -------------------------------------------------------------------- costs
const costs = [];
let priced = 0;
let unpriced = 0;

for (const c of Array.isArray(parsed.costs) ? parsed.costs : []) {
  if (!c || typeof c.label !== 'string' || !c.label.trim()) continue;

  const amount =
    typeof c.amount === 'number' && Number.isFinite(c.amount) && c.amount >= 0
      ? Math.round(c.amount * 100) / 100
      : null;

  if (amount === null) unpriced += 1;
  else priced += 1;

  const neededBy = plausibleDate(c.needed_by) ? c.needed_by : null;

  costs.push({
    label: c.label.trim(),
    category: c.category || 'other',
    amount,
    currency: (c.currency || '').toUpperCase() || null,
    isMandatory: c.is_mandatory !== false,
    neededBy,
    month: neededBy ? neededBy.slice(0, 7) : null,
    notes: c.notes?.trim() || '',
    sourceQuote: c.source_quote?.trim() || '',
    confidence: typeof c.confidence === 'number' ? c.confidence : null,
  });
}

costs.sort((a, b) => {
  if (a.neededBy && b.neededBy) return a.neededBy.localeCompare(b.neededBy);
  if (a.neededBy) return -1;
  if (b.neededBy) return 1;
  return (b.amount ?? 0) - (a.amount ?? 0);
});

// Only sum within a single currency — mixing CAD and USD into one total
// would be a quietly wrong number on a financial screen.
const currencies = [...new Set(costs.map((c) => c.currency).filter(Boolean))];
const mixedCurrency = currencies.length > 1;
if (mixedCurrency) {
  warnings.push(`Costs span multiple currencies (${currencies.join(', ')}) — totals are shown per currency.`);
}
if (unpriced > 0) {
  warnings.push(`${unpriced} cost item${unpriced === 1 ? '' : 's'} had no price in the syllabus and are excluded from the total.`);
}

const totals = {};
for (const c of costs) {
  if (c.amount === null) continue;
  const cur = c.currency || 'UNKNOWN';
  totals[cur] = totals[cur] || { mandatory: 0, optional: 0, all: 0 };
  totals[cur][c.isMandatory ? 'mandatory' : 'optional'] += c.amount;
  totals[cur].all += c.amount;
}
for (const t of Object.values(totals)) {
  t.mandatory = Math.round(t.mandatory * 100) / 100;
  t.optional = Math.round(t.optional * 100) / 100;
  t.all = Math.round(t.all * 100) / 100;
}

// Month buckets drive the cash-flow strip in the UI.
const byMonth = {};
for (const c of costs) {
  if (c.amount === null) continue;
  const bucket = c.month || 'undated';
  byMonth[bucket] = byMonth[bucket] || { month: bucket, total: 0, items: [] };
  byMonth[bucket].total = Math.round((byMonth[bucket].total + c.amount) * 100) / 100;
  byMonth[bucket].items.push(c.label);
}
const timeline = Object.values(byMonth).sort((a, b) => a.month.localeCompare(b.month));

return [{
  json: {
    course: {
      code: parsed.course?.code || '',
      title: parsed.course?.title || 'Untitled course',
      term: parsed.course?.term || '',
      institution: parsed.course?.institution || '',
    },
    events,
    costs,
    timeline,
    totals,
    warnings,
    stats: {
      eventCount: events.length,
      costCount: costs.length,
      pricedCount: priced,
      unpricedCount: unpriced,
      mixedCurrency,
      // Which model actually answered. Worth surfacing: a silent fallback to
      // a different model than configured is invisible otherwise, and it
      // changes both the cost and the quality of every figure below.
      model: response.model ?? null,
      inputTokens: response.usage?.input_tokens ?? null,
      outputTokens: response.usage?.output_tokens ?? null,
    },
    timezone,
    sourceName: meta.sourceName,
  },
}];

/**
 * One n8n item per calendar event, with the event's fields at the root of
 * `json` where the Google Calendar node expects to find them.
 *
 * This was a Split Out node. It nested each event under an `events` key
 * instead of spreading it, so `$json.start` and `$json.summary` resolved to
 * undefined. The Calendar node does `moment.tz(undefined, tz)`, which is
 * *now* rather than an error — so all eighteen events were created,
 * successfully, untitled, and stacked on today's date. A silent wrong answer
 * rather than a failure, which is why the run reported 18/18.
 *
 * Doing the mapping explicitly removes the guesswork about what the node
 * spreads and what it wraps.
 */

const plan = $input.first().json;
const events = Array.isArray(plan.events) ? plan.events : [];

return events.map((event) => {
  // Fail loudly rather than let another empty date reach Google.
  if (!event.start || !event.summary) {
    throw new Error(
      `Event is missing start or summary: ${JSON.stringify(event).slice(0, 200)}`
    );
  }
  return {
    json: {
      ...event,
      course: plan.course,
      timezone: event.timezone || plan.timezone,
    },
  };
});

/**
 * Assemble the response the web UI renders.
 *
 * Counts calendar successes and failures separately: partial success is the
 * common real-world outcome and silently reporting "done" would be a lie.
 */

const plan = $('Validate + Build Plan').first().json;
const results = $input.first().json.data || [];

let created = 0;
const failed = [];

// A failed Google Calendar item carries the error, not the event fields, so
// recover the human-readable name by position from the plan we sent in.
results.forEach((r, i) => {
  if (r?.error) {
    failed.push({
      summary: plan.events[i]?.summary ?? r.summary ?? 'an event',
      reason: String(r.error?.message ?? r.error).slice(0, 300),
    });
  } else if (r?.id || r?.htmlLink) {
    created += 1;
  }
});

const warnings = [...plan.warnings];
if (failed.length) {
  warnings.push(`${failed.length} event${failed.length === 1 ? '' : 's'} could not be added to your calendar.`);
}

return [{
  json: {
    ok: true,
    course: plan.course,
    sourceName: plan.sourceName,
    timezone: plan.timezone,
    calendar: {
      created,
      attempted: plan.events.length,
      failed,
    },
    events: plan.events,
    costs: plan.costs,
    timeline: plan.timeline,
    totals: plan.totals,
    stats: plan.stats,
    warnings,
  },
}];
